  g_message:{id:'g_message',title:'The Message',narration:'A glowing envelope flickers into view beside the camp telescope. It carries a star-map symbol that no one at Galaxy Camp has seen before.',dialogue:'“Wait… was that here a second ago?”',objective:'Discover who sent the message.',choices:[{text:'Open the envelope',nextScene:'g_signal',itemReward:'Mystery Note',starsReward:20,stat:'curiosity'},{text:'Show your friend first',nextScene:'g_team',starsReward:18,stat:'teamwork'},{text:'Follow the sparkles',nextScene:'g_trail',starsReward:22,stat:'courage'}]},
