  g_trail:{id:'g_trail',title:'The Comet Trail',narration:'The sparkles race through the forest dome and uncover a miniature robot trapped beneath a fallen antenna.',dialogue:'“Unit Pip reporting. The last star is in danger!”',objective:'Help Pip restore the antenna.',choices:[{text:'Repair Pip with the loose chip',nextScene:'g_archive',itemReward:'Robot Chip',starsReward:30,stat:'creativity'},{text:'Climb the antenna',nextScene:'g_shuttle',itemReward:'Star Fragment',starsReward:27,stat:'courage'}]},
