  m_platform:{id:'m_platform',title:'Platform Zero',narration:'A hidden staircase leads to a silent train glowing beneath the city. One seat holds a compass pointing straight down.',dialogue:'“This train isn’t on the map. Maybe the map is incomplete.”',objective:'Choose the first stop.',choices:[{text:'Board the silent train',nextScene:'m_library',itemReward:'Compass',starsReward:28,stat:'courage'},{text:'Inspect the conductor’s cabin',nextScene:'m_code',itemReward:'Flashlight',starsReward:27,stat:'curiosity'}]},
  m_keeper:{id:'m_keeper',title:'The Keeper’s Puzzle',narration:'The keeper claims not to know Platform Zero, but quietly taps a rhythm on the desk and slides you a flashlight.',dialogue:'“Some doors open for a question. Others open for a beat.”',objective:'Decode the keeper’s rhythm.',choices:[{text:'Repeat the rhythm',nextScene:'m_code',itemReward:'Flashlight',starsReward:28,stat:'creativity'},{text:'Invite the keeper along',nextScene:'m_library',starsReward:25,stat:'teamwork'}]},
  m_code:{id:'m_code',title:'The Light Code',narration:'Your light reveals invisible numbers on the tunnel wall. They spell the name of a library that vanished one hundred years ago.',dialogue:'“The city didn’t lose the library. It hid it.”',objective:'Find the vanished library.',choices:[{text:'Shine the flashlight on the door',nextScene:'m_library',requires:'Flashlight',starsReward:32,stat:'curiosity'},{text:'Fold the mystery note into a key',nextScene:'m_roof',requires:'Mystery Note',starsReward:35,stat:'creativity'}]},
  m_library:{id:'m_library',title:'The Library Below',narration:'Every book is blank until someone tells the truth. The newest book reveals that the station keeper created Platform Zero.',dialogue:'“The person hiding the secret has been helping us all along.”',objective:'Decide whether to trust the keeper.',choices:[{text:'Ask for the whole truth',nextScene:'m_truth',starsReward:35,stat:'curiosity'},{text:'Use the compass to find the last room',nextScene:'m_roof',requires:'Compass',starsReward:38,stat:'courage'},{text:'Promise to protect the library',nextScene:'m_truth',starsReward:36,stat:'teamwork'}]},
  m_roof:{id:'m_roof',title:'The City Above the City',narration:'A final elevator rises through the clouds to a second city built on the rooftops. Its lights are fading fast.',dialogue:'“Hidden City was never below us. We were looking in the wrong direction.”',objective:'Restore the rooftop beacon.',choices:[{text:'Power it with the golden ticket',nextScene:'m_beacon',requires:'Golden Ticket',starsReward:40,stat:'creativity'},{text:'Call the city together',nextScene:'m_truth',starsReward:36,stat:'teamwork'}]},
