const FEATURES=[{title:'THE STAR CODE',tag:'One secret. Five friends. A universe that believes in them.'},{title:'GALAXY CAMP',tag:'The signal came from beyond the last moon.'},{title:'DRAGON DREAMERS',tag:'Dream it. Draw it. Watch it take flight.'}];
const defaultCharacter=()=>({name:'Nova',age:'kid',type:'Human Hero',photo:'',skin:'#9a5b3c',hair:'Curly Puff',hairColor:'#24140f',outfit:'Explorer Jacket',outfitColor:'#7043bd',shoes:'High-Top Boots',accessory:'Star Pin',personality:'Brave',expression:'Confident',talent:'Solving puzzles',favorite:'Stargazing',role:'Explorer'});
const newProject=()=>({id:'movie-'+Date.now(),stage:1,character:defaultCharacter(),cast:[],world:WORLDS[1],favorites:[],recentWorlds:[],story:{mission:'',problem:'',sidekick:'',item:'',twist:'',ending:''},title:'',titleChoices:[],customTitle:false,packId:'galaxy',currentScene:'g_message',checkpoint:'g_message',choices:[],inventory:[],unlocks:[],stats:{courage:0,teamwork:0,curiosity:0,creativity:0},twistUsed:false,pendingTwist:'',twistScene:'',director:{mood:'Adventurous',location:'Original World',outfit:'Original Outfit',characters:[]},starsEarned:0,status:'Idea',ending:'',badge:'',created:new Date().toISOString(),updated:new Date().toISOString()});
const defaults={version:5,age:'kid',stars:1250,route:'home',characters:[],movies:[],compositions:[],currentCompositionId:null,editorSceneId:null,badges:['Story Explorer'],settings:{sound:true,music:true,animation:true,reduced:false,autoplay:false,textSize:'medium'},project:newProject()};
let state=loadState(),featureIndex=0;
function loadState(){try{const raw=JSON.parse(localStorage.getItem('storySparkV2'));if(!raw)return structuredClone(defaults);const restored=merge(defaults,raw);if((raw.version||0)<4&&restored.project?.status==='Idea'&&!restored.movies.some(movie=>movie.id===restored.project.id))restored.project=newProject();restored.version=5;restored.route='home';return restored}catch{return structuredClone(defaults)}}
function merge(a,b){const o=structuredClone(a);Object.keys(b||{}).forEach(k=>o[k]=b[k]&&typeof b[k]==='object'&&!Array.isArray(b[k])&&a[k]?merge(a[k],b[k]):b[k]);return o}
const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let savedStatusTimer=null;
function persistState(showFeedback=false){try{localStorage.setItem('storySparkV2',JSON.stringify(state));if(showFeedback){const status=$('#savedStatus');if(status){status.classList.add('visible');clearTimeout(savedStatusTimer);savedStatusTimer=setTimeout(()=>status.classList.remove('visible'),1200)}}return true}catch(error){console.warn('Local save recovery:',error);toast('Your latest change could not be saved. Keep this tab open and try removing an older movie.');return false}}
function save(){state.project.updated=new Date().toISOString();return persistState(true)}
function autosave(){const p=state.project;p.updated=new Date().toISOString();const i=state.movies.findIndex(m=>m.id===p.id);if(i>=0)state.movies[i]=structuredClone(p);return persistState(false)}
function saveProject(showFeedback=false){const p=state.project;p.updated=new Date().toISOString();const i=state.movies.findIndex(m=>m.id===p.id),copy=structuredClone(p);if(i<0)state.movies.unshift(copy);else state.movies[i]=copy;return persistState(showFeedback)}
function resetProject(){state.project=newProject();state.project.character.age=state.age}
function pack(){return PACKS[state.project.packId]||PACKS.galaxy}
function currentScene(){return pack().scenes[state.project.currentScene]||pack().scenes[pack().start]}
function composition(){return state.compositions.find(c=>c.movieId===state.currentCompositionId)||null}
function saveComposition(comp){comp=MovieStudio.validate(comp);const i=state.compositions.findIndex(c=>c.movieId===comp.movieId);if(i<0)state.compositions.unshift(comp);else state.compositions[i]=comp;state.currentCompositionId=comp.movieId;state.editorSceneId=state.editorSceneId&&comp.scenes.some(s=>s.id===state.editorSceneId)?state.editorSceneId:comp.scenes[0]?.id;const project=state.movies.find(m=>m.id===comp.projectId);if(project){project.compositionId=comp.movieId;project.movieDuration=MovieStudio.totalDuration(comp);project.movieStatus=comp.status;project.updated=comp.updatedDate}save();return comp}
function buildComposition(quick=false){try{let comp=MovieStudio.build(state.project,pack(),{quick});if(quick)comp=MovieStudio.quickPolish(comp);comp.transitionSettings.reducedMotion=state.settings.reduced||matchMedia('(prefers-reduced-motion: reduce)').matches;saveComposition(comp);return comp}catch(e){toast(e.message||'We could not build this movie yet.');return null}}
function ageText(text){const max=AGE[state.age].words;if(state.age==='toddler')return text.split(/[.!?]/)[0]+'.';const w=text.split(' ');return w.length>max?w.slice(0,max).join(' ')+'…':text}
function titleChoices(){const p=state.project,w=p.world.name.split(' ').map(x=>x.toUpperCase()).join(' '),item=(p.story.item||'MYSTERY').toUpperCase(),names=[`THE ${item}`,`MYSTERY AT ${w}`,`THE SECRET OF ${w}`,`${p.character.name.toUpperCase()} AND THE LOST ${item}`,`ESCAPE FROM ${w}`,`THE LAST STAR MAP`];p.titleChoices=[...new Set(names)].sort(()=>Math.random()-.5).slice(0,3);if(!p.customTitle&&!p.titleChoices.includes(p.title))p.title=''}
function shell(content){return `<div class="app"><aside class="sidebar" id="sidebar"><div class="brand"><div class="brand-mark">STORY <span>SPARK</span><em>CINEMA™</em></div><p>Where Little Ideas<br>Become BIG Movies.</p></div><nav class="nav">${[['home','⌂','HOME'],['create','🎬','CREATE'],['movies','🎞️','MY MOVIES'],['characters','⭐','CHARACTERS'],['worlds','🌐','MOVIE WORLDS'],['rewards','🏆','REWARDS'],['settings','⚙️','SETTINGS']].map(n=>`<button data-route="${n[0]}" class="${state.route===n[0]?'active':''}"><span class="ico">${n[1]}</span>${n[2]}</button>`).join('')}</nav><div class="movie-box"><h3>SHAKE THE<br>MOVIE BOX!</h3><div class="q">?</div><p>Surprise me with a random movie!</p><button class="btn gold" data-action="surprise-project">🎲 SHAKE IT</button><button class="btn ghost upload-story-shortcut" data-action="import-story">📖 UPLOAD STORY</button></div></aside><div class="mobile-top"><button data-action="menu">☰</button><strong>STORY SPARK CINEMA™</strong></div><main class="main">${topbar()}${content}</main>${ribbon()}</div>`}
function topbar(){return `<header class="topbar"><div class="headline"><h1>LIGHTS. CAMERA. IMAGINATION. <em>You’re the Director!</em></h1><p>Create a story. Turn it into a movie. Watch your imagination premiere.</p></div><button class="pill age-mode-pill" data-action="settings" title="Change age range"><span>${AGE[state.age].emoji}</span> ${AGE[state.age].label} ${AGE[state.age].years}</button><div class="pill stars">⭐ <span>${state.stars.toLocaleString()}</span></div><button class="pill" data-action="profile"><span class="avatar">🎥</span> Hey, Director!</button></header>`}
function ribbon(){return `<div class="footer-ribbon">${[['🛡️','SAFE & KID FRIENDLY'],['🚫','NO ADS'],['🪄','CREATIVE FREEDOM'],['☁️','SAVE YOUR MOVIES'],['🏆','EARN BADGES & REWARDS'],['✈️','PLAY OFFLINE ANYTIME']].map(x=>`<div class="ribbon-item"><span>${x[0]}</span>${x[1]}</div>`).join('')}</div>`}
function home(){const recent=state.movies.slice().sort((a,b)=>new Date(b.updated)-new Date(a.updated)).slice(0,3);return `<div class="home-grid"><section class="age-wrap"><p class="script">Choose Your Age Range</p><div class="ages">${Object.entries(AGE).map(([k,a])=>`<button class="age-card ${state.age===k?'selected':''}" style="--c:${a.color}" data-age="${k}"><span class="age-emoji">${a.emoji}</span><strong>${a.label.toUpperCase()}</strong><small>${a.years}</small></button>`).join('')}</div><p class="safe">🔒 All content is 100% kid-safe, age-appropriate, and imagination-approved. 🛡️</p></section><section class="featured card"><div class="featured-content"><div class="eyebrow">★ Featured Adventure ★</div><h2>${FEATURES[featureIndex].title}</h2><p>${FEATURES[featureIndex].tag}</p><div class="actions"><button class="btn" data-action="trailer">WATCH TRAILER ▶</button><button class="btn gold" data-action="featured-start">BEGIN ADVENTURE</button></div></div></section><section class="quick card"><div class="section-head">— WHAT WILL YOU CREATE TODAY? —</div><div class="quick-grid">${[['🎬','CREATE A MOVIE','Build your movie step by step','new-movie','#6a87ff'],['🪄','SPARK A STORY','Give me an idea and I’ll build it','surprise-project','#ff5fb4'],['🎥','DIRECTOR MODE','Full creative control. You call the shots.','director','#f1a52b'],['🎞️','CONTINUE MOVIE','Resume your latest unfinished adventure','continue','#55d9d0'],['🍿','MOVIE THEATER','Watch your finished masterpieces','theater','#ff5364']].map(x=>`<button class="quick-card" style="--c:${x[4]}" data-action="${x[3]}"><span class="ico">${x[0]}</span><strong>${x[1]}</strong><small>${x[2]}</small></button>`).join('')}</div></section><section class="theater card"><div class="section-head">✦ NEW IN THEATER! ✦</div><div class="poster-row">${[['🧪','SLIME SQUAD ACADEMY','#39bf78'],['🐉','DRAGON DREAMERS','#34a6ae'],['🔮','THE ECHO QUEST','#9b58ce']].map(x=>`<div class="mini-poster" style="--p:${x[2]}"><span class="symbol">${x[0]}</span><strong>${x[1]}</strong></div>`).join('')}</div></section><section class="lower"><div class="card"><div class="section-head">BUILD YOUR MOVIE</div><div class="steps">${[['1','⭐','STAR','#b96eff'],['2','🌐','WORLD','#42cff4'],['3','📖','STORY','#61dd82'],['4','🎬','SCENES','#8197ff'],['5','🏅','FINISH','#ffc248']].map(x=>`<div><div class="step-bubble" style="--c:${x[4]}">${x[1]}</div><strong>${x[0]} ${x[2]}</strong></div>`).join('')}</div></div><div class="card"><div class="section-head">MY RECENT MOVIES</div><div class="movie-list">${(recent.length?recent:[{title:'The Great Dino Rescue',world:{icon:'🦕'},status:'Completed'},{title:'Mystery at Galaxy Camp',world:{icon:'🚀'},status:'In Progress'}]).map(m=>movieRow(m)).join('')}</div></div><div class="card"><div class="section-head">STUDIO TOOLS</div><div class="tools">${[['🧑','CHARACTER MAKER','characters'],['👕','COSTUME DESIGNER','create'],['🌄','SCENE BUILDER','create'],['🎵','SOUND STUDIO','director'],['🔤','TEXT & TITLES','poster'],['🎙️','VOICE & DIALOGUE','director']].map(x=>`<button class="tool" data-action="${x[2]}"><span>${x[0]}</span>${x[1]}</button>`).join('')}</div></div></section></div>`}
function polishHome(html){let polished=html.replace('<div class="home-grid">','<div class="home-grid"><section class="home-journey"><div><i>1</i><span><b>CREATE A STORY</b><small>Choose your star, world, and adventure.</small></span></div><em>→</em><div><i>2</i><span><b>TURN IT INTO A MOVIE</b><small>Build and shape your cinematic timeline.</small></span></div><em>→</em><div><i>3</i><span><b>WATCH YOUR MOVIE</b><small>Premiere, replay, and export your feature.</small></span></div></section>');if(!state.movies.length){const samples=[{title:'The Great Dino Rescue',world:{icon:'🦕'},status:'Completed'},{title:'Mystery at Galaxy Camp',world:{icon:'🚀'},status:'In Progress'}].map(m=>movieRow(m)).join('');polished=polished.replace(samples,'<div class="home-empty"><span>🎞️</span><div><b>Your first feature starts here.</b><small>Create a story and it will appear on this marquee.</small></div><button class="play" aria-label="Create your first movie" data-action="new-movie">+</button></div>')}return polished}
function movieRow(m){return `<div class="movie-row"><div class="thumb">${m.world?.icon||'🎬'}</div><div><strong>${esc(m.title||'Untitled Movie')}</strong><small>${esc(m.world?.genre||'Adventure')} • ${esc(m.status)}</small></div><button class="play" aria-label="Open ${esc(m.title||'movie')}" ${m.id?`data-resume="${m.id}"`:'data-action="featured-start"'}>▶</button></div>`}
function progress(){const p=state.project;return `<div class="creation-progress">${['Create Your Star','Pick Your World','Build Your Story','Play Your Movie','Movie Finale'].map((x,i)=>`<button class="progress-step ${p.stage===i+1?'active':''} ${p.stage>i+1?'done':''}" data-jump="${i+1}" ${i+1>p.stage?'disabled':''}><i>${p.stage>i+1?'✓':i+1}</i><span>${x}</span></button>`).join('')}</div>`}
function create(){const p=state.project;return `<div class="flow-head"><div><div class="eyebrow">MOVIE CREATION STUDIO</div><h2 class="page-title">${['','CREATE YOUR STAR','PICK YOUR WORLD','BUILD YOUR STORY','PLAY YOUR MOVIE','MOVIE FINALE'][p.stage]}</h2></div><div class="flow-actions">${p.stage===1?'<button class="btn ghost" data-route="home">← HOME</button>':''}<span class="pill">STEP ${p.stage} OF 5</span></div></div>${progress()}<section class="card content-card creation-stage">${p.stage===1?characterStageWithPhoto():p.stage===2?worldStage():p.stage===3?storyStage():p.stage===4?playerStageWithPhoto():finaleStage()}</section>`}
function characterStage(){const c=state.project.character,opts={type:['Human Hero','Robot Hero','Magical Hero','Animal Hero'],hair:['Curly Puff','Braids','Waves','Short Curls','Locs','Straight','Covered'],outfit:['Explorer Jacket','Science Suit','Hero Hoodie','Royal Adventure','Sports Gear','Music Star'],shoes:['High-Top Boots','Sneakers','Trail Boots','Light-Up Shoes'],accessory:['Star Pin','Glasses','Headband','Cape','Utility Bag','None'],personality:['Brave','Curious','Funny','Kind','Clever','Bold'],expression:['Confident','Joyful','Curious','Determined'],talent:['Solving puzzles','Making inventions','Helping friends','Finding clues','Creating music','Amazing teamwork'],role:['Explorer','Inventor','Guardian','Detective','Dreamer','Team Captain']};return `<div class="creator-layout"><div class="avatar-stage"><div class="live-avatar" style="--skin:${c.skin};--hair:${c.hairColor};--outfit:${c.outfitColor}"><div class="avatar-hair">${c.hair==='Covered'?'◆':'✦'}</div><div class="avatar-head"><span>${c.expression==='Joyful'?'◡':c.expression==='Determined'?'⌣':'•‿•'}</span></div><div class="avatar-body">${c.type.includes('Robot')?'⚙':c.accessory==='Cape'?'★':'✦'}</div><div class="avatar-shoes"></div></div><h2>${esc(c.name)}</h2><p>${c.personality} ${c.role} • ${c.talent}</p><div class="preview-tags"><span>${c.hair}</span><span>${c.outfit}</span><span>${c.accessory}</span></div></div><div class="creator-controls"><div class="form-grid"><div class="field"><label>CHARACTER NAME</label><input data-char="name" value="${esc(c.name)}" maxlength="24"></div><div class="field"><label>AGE RANGE</label><input value="${AGE[state.age].label} ${AGE[state.age].years}" disabled></div></div><div class="visual-options">${selector('CHARACTER TYPE','type',opts.type,c.type)}${colorSelector('SKIN TONE','skin',['#f5cfad','#dca578','#b97850','#9a5b3c','#6b3b29','#3e251e'],c.skin)}${selector('HAIR STYLE','hair',opts.hair,c.hair)}${colorSelector('HAIR COLOR','hairColor',['#17100d','#3b2418','#754529','#b47742','#e1ba76','#6a345f'],c.hairColor)}${selector('OUTFIT','outfit',opts.outfit,c.outfit)}${colorSelector('OUTFIT COLOR','outfitColor',['#7043bd','#167fa1','#d33c74','#d88819','#24724d','#313c7e'],c.outfitColor)}${selector('SHOES','shoes',opts.shoes,c.shoes)}${selector('ACCESSORY','accessory',opts.accessory,c.accessory)}${selector('PERSONALITY','personality',opts.personality,c.personality)}${selector('EXPRESSION','expression',opts.expression,c.expression)}${selector('SPECIAL TALENT','talent',opts.talent,c.talent)}${selector('ROLE IN STORY','role',opts.role,c.role)}<div class="field"><label>FAVORITE THING</label><input data-char="favorite" value="${esc(c.favorite)}" maxlength="32"></div></div><div class="actions wide-actions"><button class="btn ghost" data-action="reset-character">RESET</button><button class="btn" data-action="random-character">🎲 RANDOMIZE</button><button class="btn" data-add-cast="Friend">+ FRIEND</button><button class="btn" data-add-cast="Sibling">+ SIBLING</button><button class="btn" data-add-cast="Sidekick">+ SIDEKICK</button><button class="btn gold" data-action="save-character">SAVE CHARACTER & CONTINUE</button></div>${state.project.cast.length?`<div class="cast-strip"><strong>YOUR CAST:</strong>${state.project.cast.map((x,i)=>`<span>${x.type}: ${esc(x.name)} <button data-remove-cast="${i}">×</button></span>`).join('')}</div>`:''}</div></div>`}
function characterStageWithPhoto(){const c=state.project.character;let html=characterStage();html=html.replace('<div class="live-avatar" style=',`<div class="live-avatar ${c.photo?'has-star-photo':''}" style=`);if(c.photo)html=html.replace('<div class="avatar-hair">',`<img class="star-photo" src="${esc(c.photo)}" alt="${esc(c.name)} movie star photo"><div class="avatar-hair">`);const upload=`<div class="star-upload-card"><div class="star-upload-copy"><span>📸</span><div><strong>PUT A REAL PERSON IN THE MOVIE</strong><small>Choose a clear portrait photo. It stays inside this browser.</small></div></div><div class="actions"><label class="btn gold upload-label">${c.photo?'CHANGE PHOTO':'UPLOAD YOUR STAR'}<input id="starPhotoInput" type="file" accept="image/jpeg,image/png,image/webp" hidden></label>${c.photo?'<button class="btn ghost" data-action="remove-star-photo">USE ILLUSTRATED STAR</button>':''}</div></div>`;return html.replace('<div class="creator-controls">','<div class="creator-controls">'+upload)}
function selector(label,key,values,current){return `<div class="option-group"><label>${label}</label><div>${values.map((v,i)=>`<button class="option-chip ${current===v?'selected':''}" data-char-option="${key}" data-value="${esc(v)}"><b>${['✦','◆','●','▲','★','⬟'][i%6]}</b>${v}</button>`).join('')}</div></div>`}
function colorSelector(label,key,values,current){return `<div class="option-group"><label>${label}</label><div class="swatches">${values.map(v=>`<button class="swatch ${current===v?'selected':''}" style="--swatch:${v}" data-char-option="${key}" data-value="${v}" aria-label="${label} ${v}"></button>`).join('')}</div></div>`}
function worldStage(){const p=state.project,w=p.world;return `<div class="world-layout"><aside class="world-hero" style="--world1:${w.colors[0]};--world2:${w.colors[1]}"><span class="world-icon">${w.icon}</span><div><div class="eyebrow">YOUR MOVIE WORLD</div><h2>${w.name}</h2><p>${w.desc}</p><span class="badge">${w.genre}</span><span class="badge">${w.mood}</span></div></aside><div><div class="world-toolbar"><button class="btn" data-action="random-world">✨ SURPRISE ME</button><button class="btn ${p.favorites.includes(w.name)?'gold':''}" data-action="favorite-world">★ FAVORITE</button><span>${p.recentWorlds.length?'Recently used: '+p.recentWorlds.slice(0,2).join(', '):'Choose a world to begin'}</span></div><div class="world-grid">${WORLDS.map((x,i)=>`<button class="world-card ${w.name===x.name?'selected':''}" style="--world1:${x.colors[0]};--world2:${x.colors[1]}" data-world="${i}"><span>${x.icon}</span><h3>${x.name}</h3><b>${x.genre} • ${x.mood}</b><p>${x.desc}</p>${p.favorites.includes(x.name)?'<i>★</i>':''}</button>`).join('')}</div><div class="actions"><button class="btn ghost" data-action="prev-stage">BACK</button><button class="btn gold" data-action="choose-world">CHOOSE THIS WORLD</button></div></div></div>`}
function storyStage(){const p=state.project;if(!p.titleChoices.length)titleChoices();return `<div class="story-layout"><div class="story-builder">${Object.entries(STORY_OPTIONS).map(([key,vals])=>`<div class="story-section"><label>${key==='item'?'SPECIAL ITEM':key.toUpperCase()}</label><div>${vals.map(v=>`<button class="story-option ${p.story[key]===v?'selected':''}" data-story-key="${key}" data-value="${esc(v)}">${storyIcon(key)} ${v}</button>`).join('')}</div></div>`).join('')}<div class="title-lab"><div class="title-head"><div><label>AUTOMATIC MOVIE TITLE</label><h3>Choose Your Marquee Title</h3></div><button class="btn" data-action="shuffle-titles">↻ SHUFFLE TITLES</button></div><div class="title-choices">${p.titleChoices.map(t=>`<button class="title-choice ${p.title===t&&!p.customTitle?'selected':''}" data-title="${esc(t)}">${t}</button>`).join('')}</div><div class="field"><label>OR ENTER MY OWN TITLE</label><input id="customTitle" placeholder="Type your movie title" value="${p.customTitle?esc(p.title):''}"></div></div><div class="actions"><button class="btn ghost" data-action="prev-stage">BACK</button><button class="btn" data-action="surprise-story">✨ SURPRISE ME</button><button class="btn gold" data-action="start-movie">ROLL CAMERA</button></div></div><aside class="movie-so-far"><div class="eyebrow">LIVE MOVIE PREVIEW</div><h2>YOUR MOVIE SO FAR</h2><div class="mini-marquee">${esc(p.title||'Your Title')}</div>${[['MOVIE STAR',p.character.name],['WORLD',p.world.name],['MISSION',p.story.mission],['SIDEKICK',p.story.sidekick],['SPECIAL ITEM',p.story.item],['MOOD',p.world.mood]].map(x=>`<div><small>${x[0]}</small><strong>${esc(x[1])}</strong></div>`).join('')}<div class="world-mini" style="--world1:${p.world.colors[0]};--world2:${p.world.colors[1]}">${p.world.icon}</div></aside></div>`}
function storyIcon(k){return {mission:'🎯',problem:'⚠',sidekick:'★',item:'◆',twist:'✨',ending:'🏁'}[k]}
function playerStage(){const p=state.project,s=currentScene(),choices=(s.choices||[]).filter(c=>!c.requires||p.inventory.includes(c.requires)).slice(0,AGE[state.age].max);return `<div class="player-top"><div><div class="eyebrow">SCENE ${p.choices.length+1} • ${p.title}</div><h2>${s.title}</h2></div><div class="scene-stars">⭐ ${p.starsEarned}</div></div><div class="cinema-screen" style="--world1:${p.world.colors[0]};--world2:${p.world.colors[1]}"><div class="cinema-atmosphere"></div><span class="scene-world-icon">${p.world.icon}</span><div class="scene-character">${p.character.name.slice(0,1).toUpperCase()}</div><div class="scene-label">${esc(p.director.location==='Original World'?p.world.name:p.director.location)} • ${esc(p.director.mood)}</div></div>${p.pendingTwist&&p.twistScene===s.id?`<div class="twist-event">✨ PLOT TWIST: ${esc(p.pendingTwist)}</div>`:''}<div class="player-grid"><article class="scene-copy"><p class="narration">${ageText(s.narration)}</p><blockquote>${ageText(s.dialogue)}</blockquote><div class="objective"><small>CURRENT OBJECTIVE</small><strong>${s.objective}</strong></div>${s.endingFlag?`<button class="btn gold finale-button" data-action="reach-finale">VIEW YOUR MOVIE FINALE ✨</button>`:`<h3>WHAT DO YOU DO?</h3><div class="movie-choices">${choices.map((c,i)=>`<button data-movie-choice="${i}"><span>${String.fromCharCode(65+i)}</span><strong>${c.text}</strong>${c.requires?`<small>Uses ${c.requires}</small>`:''}</button>`).join('')}</div>`}</article><aside><div class="backpack"><h3>🎒 MOVIE BACKPACK</h3>${p.inventory.length?`<div class="inventory-grid">${p.inventory.map(i=>`<div>${itemIcon(i)}<small>${i}</small></div>`).join('')}</div>`:'<p>Your first collectible is waiting!</p>'}</div><button class="twist-button" data-action="plot-twist" ${p.twistUsed?'disabled':''}>${p.twistUsed?'✓ PLOT TWIST USED':'ADD A PLOT TWIST ✨'}</button><button class="director-mini" data-action="director">🎥 OPEN DIRECTOR MODE</button><button class="btn ghost autosave-note" data-action="save-progress">☁ SAVE PROGRESS</button></aside></div>`}
function playerStageWithPhoto(){const c=state.project.character,html=playerStage();if(!c.photo)return html;const original=`<div class="scene-character">${c.name.slice(0,1).toUpperCase()}</div>`;return html.replace(original,`<div class="scene-character real-star"><img src="${esc(c.photo)}" alt="${esc(c.name)} in this movie scene"></div>`)}
function itemIcon(i){if(/key/i.test(i))return'🔑';if(/map|note/i.test(i))return'🗺️';if(/crystal|star/i.test(i))return'💎';if(/chip/i.test(i))return'🔷';if(/ticket/i.test(i))return'🎟️';if(/feather/i.test(i))return'🪶';if(/flash/i.test(i))return'🔦';return'◆'}
function directorPage(){const p=state.project,controls=[['mood','Movie Mood',['Adventurous','Funny','Mysterious','Magical','Heartwarming']],['location','Scene Location',['Original World','Moonlit Castle','Secret Tunnel','Sky Bridge','Hidden Laboratory']],['outfit','Star Outfit',['Original Outfit','Hero Upgrade','Mystery Coat','Festival Costume','Cosmic Suit']]];return page('DIRECTOR MODE™',`<div class="director-console"><div class="director-screen" style="--world1:${p.world.colors[0]};--world2:${p.world.colors[1]}"><span>${p.world.icon}</span><div class="eyebrow">LIVE DIRECTOR PREVIEW</div><h2>${esc(p.title||'Your Movie')}</h2><p>${p.director.mood} • ${p.director.location} • ${p.director.outfit}</p></div><div class="director-panels"><p class="script">You Call the Shots.</p><details open><summary>🎬 SCENE & CAMERA</summary><div class="director-fields">${controls.slice(0,2).map(c=>`<div class="field"><label>${c[1].toUpperCase()}</label><select data-direct-select="${c[0]}">${c[2].map(x=>`<option ${p.director[c[0]]===x?'selected':''}>${x}</option>`).join('')}</select></div>`).join('')}</div></details><details open><summary>🎭 STAR & STORY</summary>${controls.slice(2).map(c=>`<div class="field"><label>${c[1].toUpperCase()}</label><select data-direct-select="${c[0]}">${c[2].map(x=>`<option ${p.director[c[0]]===x?'selected':''}>${x}</option>`).join('')}</select></div>`).join('')}<div class="director-actions">${['Add Character','Make It Funnier','Add Mystery','Add Magic','Add Action','Rewrite Dialogue'].map((x,i)=>`<button class="choice-card" data-direct-action="${x}"><span class="big">${['🧑','😂','🔎','✨','⚡','✍️'][i]}</span><strong>${x}</strong></button>`).join('')}</div></details><div class="director-return"><span>Changes save automatically ✨</span><button class="btn gold" data-action="back-to-movie">← BACK TO MY MOVIE</button></div></div></div>`)}
function finaleStage(){const p=state.project,s=currentScene(),hasMovie=state.compositions.some(c=>c.projectId===p.id);return `<div class="finale"><div class="finale-burst">✦</div><div class="eyebrow">A STORY SPARK CINEMA ORIGINAL</div><h1>${esc(p.title)}</h1><p class="script">${esc(p.ending||s.endingFlag||p.story.ending)}</p><div class="finale-summary"><div class="finale-poster" style="--world1:${p.world.colors[0]};--world2:${p.world.colors[1]}"><span>${p.world.icon}</span><h2>${esc(p.title)}</h2><b>STARRING ${esc(p.character.name).toUpperCase()}</b></div><div><h2>YOUR MOVIE MAGIC</h2><p>${esc(s.summary||`In ${p.world.name}, ${p.character.name} proved that imagination can change any ending.`)}</p>${[['ENDING REACHED',p.ending],['MOVIE STAR',p.character.name],['WORLD',p.world.name],['TREASURES',p.inventory.join(', ')||'Courage'],['STARS EARNED',p.starsEarned],['BADGE',p.badge||'Movie Maker']].map(x=>`<div class="result-row"><small>${x[0]}</small><strong>${esc(x[1])}</strong></div>`).join('')}<div class="build-movie-callout"><span>🎬</span><div><h3>TURN THIS STORY INTO A MINI MOVIE</h3><p>We’ll create the title, cinematic scenes, ending, and credits automatically.</p></div><button class="btn gold" data-action="build-movie">${hasMovie?'EDIT MY MOVIE':'BUILD MY MOVIE 🎬'}</button><button class="btn" data-action="quick-movie">MAKE IT FOR ME ✨</button></div></div></div><div class="actions finale-actions"><button class="btn" data-action="watch-again">WATCH AGAIN</button><button class="btn" data-action="try-ending">TRY ANOTHER ENDING</button><button class="btn" data-action="poster">CREATE POSTER</button><button class="btn" data-action="sequel">MAKE A SEQUEL</button><button class="btn gold" data-action="save-movie">SAVE MOVIE</button><button class="btn ghost" data-action="new-movie">START NEW MOVIE</button></div></div>`}
function posterPage(){const p=state.project,layout=p.posterLayout||'Epic',tagline=p.tagline||'Every choice lights a new path.';return page('MOVIE POSTER MAKER',`<div class="poster-workshop"><div class="poster-preview poster-${layout.toLowerCase()}" style="--world1:${p.world.colors[0]};--world2:${p.world.colors[1]}"><div class="eyebrow">A STORY SPARK CINEMA ORIGINAL</div><span class="poster-genre">${esc(layout)} PREMIERE</span><span class="poster-world">${p.world.icon}</span><span class="poster-avatar">${p.character.name[0].toUpperCase()}</span><h2>${esc(p.title||'YOUR MOVIE')}</h2><p>“${esc(tagline)}”</p><strong>${esc(p.world.genre)} • STARRING ${esc(p.character.name).toUpperCase()}</strong><small>DIRECTED BY YOU • STORY SPARK CINEMA™</small></div><div><p class="script">Choose Your Premiere Look</p><p class="poster-help">Give your movie a look worthy of opening night.</p><div class="poster-layouts">${['Epic','Magical','Comedy','Mystery','Adventure','Sci-Fi'].map((x,i)=>`<button class="choice-card ${layout===x?'selected':''}" data-poster-layout="${x}"><span class="big">${['🌟','✨','😄','🔎','🧭','🪐'][i]}</span><strong>${x}</strong></button>`).join('')}</div><div class="field"><label>POSTER TAGLINE</label><input id="posterTagline" value="${esc(tagline)}" maxlength="90"></div><button class="btn gold" data-action="save-poster">SAVE PREMIERE POSTER</button></div></div>`)}
function moviesPage(){const orphanComps=state.compositions.filter(c=>!c.projectId||!state.movies.some(m=>m.id===c.projectId));const count=state.movies.length+orphanComps.length;return page('MY MOVIES',`<div class="library-toolbar"><button class="btn gold" data-action="new-movie">+ CREATE STORY</button><button class="btn" data-action="import-story">📖 UPLOAD / PASTE YOUR STORY</button></div>${count?`<div class="grid movie-library">${state.movies.map(m=>{const c=state.compositions.find(x=>x.projectId===m.id);return `<div class="choice-card movie-project-card"><div class="movie-card-art" style="--world1:${m.world?.colors?.[0]||'#17265d'};--world2:${m.world?.colors?.[1]||'#a45cf2'}"><span>${m.world?.icon||'🎬'}</span><b>${esc(m.title||'Untitled Movie')}</b></div><h3>${esc(m.title||'Untitled Movie')}</h3><span class="badge">${c?c.status:m.status}</span><p>${esc(m.world?.genre)} • ${c?TimelineEditor.formatTime(MovieStudio.totalDuration(c)):'Story only'} • ${AGE[m.character?.age||state.age]?.label||'Kids'}</p><small>Updated ${new Date(c?.updatedDate||m.updated).toLocaleDateString()}</small><div class="movie-card-actions">${c?`<button class="btn gold" data-play-composition="${c.movieId}">PLAY</button><button class="btn" data-edit-composition="${c.movieId}">EDIT MOVIE</button>`:''}<button class="btn" data-resume="${m.id}">CONTINUE STORY</button><button class="btn ghost" data-duplicate-movie="${m.id}">DUPLICATE</button><button class="btn danger-btn" data-delete-movie="${m.id}">🗑 DELETE</button></div></div>`}).join('')}${orphanComps.map(c=>`<div class="choice-card movie-project-card"><div class="movie-card-art" style="--world1:${c.selectedWorld?.colors?.[0]||'#17265d'};--world2:${c.selectedWorld?.colors?.[1]||'#a45cf2'}"><span>${c.selectedWorld?.icon||'📖'}</span><b>${esc(c.title||'Imported Story')}</b></div><h3>${esc(c.title||'Imported Story')}</h3><span class="badge">${c.status||'Editing'}</span><p>${esc(c.genre||'Adventure')} • ${TimelineEditor.formatTime(MovieStudio.totalDuration(c))} • Imported Story</p><small>Updated ${new Date(c.updatedDate||c.createdDate).toLocaleDateString()}</small><div class="movie-card-actions"><button class="btn gold" data-play-composition="${c.movieId}">PLAY</button><button class="btn" data-edit-composition="${c.movieId}">EDIT MOVIE</button><button class="btn ghost" data-duplicate-composition="${c.movieId}">DUPLICATE</button><button class="btn danger-btn" data-delete-composition="${c.movieId}">🗑 DELETE</button></div></div>`).join('')}</div>`:`<div class="empty">🎞️ No saved movies yet.<br><br><button class="btn gold" data-action="import-story">📖 UPLOAD OR PASTE YOUR FIRST STORY</button></div>`}`)}
function charactersPage(){return page('MY CHARACTERS',`<div class="library-toolbar"><button class="btn gold" data-action="new-movie">+ CREATE A MOVIE STAR</button><span class="library-note">Build a cast you can bring into new adventures.</span></div>${state.characters.length?`<div class="grid saved-grid character-library">${state.characters.map((c,i)=>`<div class="choice-card"><div class="saved-avatar" style="--skin:${c.skin};--outfit:${c.outfitColor}">${c.name[0]}</div><div class="eyebrow">${esc(c.type||'MOVIE STAR')}</div><h3>${esc(c.name)}</h3><p>${esc(c.personality)} ${esc(c.role)} • ${esc(c.talent||'Story Spark')}</p><div class="card-actions"><button class="btn gold" data-use-char="${i}">USE IN MOVIE</button><button class="btn ghost" data-delete-char="${i}">REMOVE</button></div></div>`).join('')}</div>`:'<div class="empty"><h2>Your cast is waiting in the wings.</h2><p>Create your first movie star and give them an adventure.</p><button class="btn gold" data-action="new-movie">CREATE MY FIRST STAR</button></div>'}`)}
function worldsPage(){return page('MOVIE WORLDS',`<div class="world-grid">${WORLDS.map((w,i)=>`<button class="world-card" style="--world1:${w.colors[0]};--world2:${w.colors[1]}" data-world-start="${i}"><span>${w.icon}</span><h3>${w.name}</h3><b>${w.genre} • ${w.mood}</b><p>${w.desc}</p></button>`).join('')}</div>`)}
function rewardsPage(){const rewards=[['First Movie','First Feature','Finish your first original'],['Plot Twist Pro','Plot Twist Pro','Change the story when no one expects it'],['Story Explorer','World Explorer','Begin an adventure in a movie world'],['Character Creator','Story Spark','Create an unforgettable movie star'],['Galaxy Guardian','Movie Maker','Reach a heroic galaxy ending'],['Keeper of the Dawn','Scene Master','Bring sunrise back to a magical world'],['Master Detective','Ending Hunter','Solve the mystery of Hidden City'],['Legendary Director','Director Level Up','Master the advanced studio']];return page('REWARDS',`<div class="rewards-marquee"><div><div class="eyebrow">YOUR PREMIERE COLLECTION</div><h2>⭐ ${state.stars.toLocaleString()} STORY STARS</h2><p>Every choice, ending, and finished feature adds to your legend.</p></div><span>🏆</span></div><div class="grid saved-grid rewards-grid">${rewards.map(([key,title,description],i)=>`<div class="choice-card ${state.badges.includes(key)?'selected':'locked'}"><span class="big">${['🏅','🌀','🧭','⭐','🌌','🌅','🔎','🏆'][i]}</span><div class="eyebrow">${state.badges.includes(key)?'ACHIEVEMENT UNLOCKED':'COMING SOON'}</div><h3>${title}</h3><p>${state.badges.includes(key)?description:'Keep directing to reveal this award.'}</p></div>`).join('')}</div>`)}
function settingsPage(){const s=state.settings;return page('SETTINGS',`<div class="settings-list">${[['sound','Sound effects'],['music','Background music'],['animation','Magical animations'],['reduced','Reduced motion'],['autoplay','Autoplay story text']].map(x=>`<div class="setting"><span>${x[1]}</span><button class="switch ${s[x[0]]?'on':''}" data-setting="${x[0]}"></button></div>`).join('')}<div class="setting"><span>Age range</span><select id="settingAge">${Object.entries(AGE).map(([k,a])=>`<option value="${k}" ${state.age===k?'selected':''}>${a.label}</option>`).join('')}</select></div><div class="setting"><span>Text size</span><select id="textSize">${['small','medium','large'].map(x=>`<option ${s.textSize===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="setting"><span>Reset all app data</span><button class="btn" data-action="reset-data">RESET</button></div></div>`)}
function theaterPage(){const ready=state.compositions.filter(c=>c.status==='Finished'||c.status==='Ready to Play'||state.movies.find(m=>m.id===c.projectId)?.status==='Completed'),featured=ready[0],rest=ready.slice(1);const card=c=>`<button class="streaming-card" style="--world1:${c.selectedWorld?.colors?.[0]||'#17265d'};--world2:${c.selectedWorld?.colors?.[1]||'#a45cf2'}" data-play-composition="${c.movieId}"><span>${c.selectedWorld?.icon||'🎬'}</span><div class="eyebrow">STORY SPARK ORIGINAL</div><h3>${esc(c.title)}</h3><p>${esc(c.genre)} • ${TimelineEditor.formatTime(MovieStudio.totalDuration(c))}</p><b>▶ PLAY MOVIE</b></button>`;return page('MOVIE THEATER',`<div class="theater-hero"><span>🍿</span><div><div class="eyebrow">WELCOME TO YOUR PRIVATE PREMIERE</div><h2>YOUR STORIES. NOW SHOWING.</h2><p>Choose a feature and watch it continuously from opening title through final credits.</p></div></div>${featured?`<div class="theater-row-head"><div><span>FEATURED PREMIERE</span><h2>Tonight’s Main Feature</h2></div><small>${ready.length} movie${ready.length===1?'':'s'} in your theater</small></div><div class="featured-premiere">${card(featured)}<div class="premiere-info"><div class="eyebrow">READY FOR THE BIG SCREEN</div><h2>${esc(featured.title)}</h2><p>${esc(featured.tagline||'Your Story. Your Movie. Your Magic.')}</p><div><span class="badge">${esc(featured.genre)}</span><span class="badge">${TimelineEditor.formatTime(MovieStudio.totalDuration(featured))}</span><span class="badge">${esc(featured.status)}</span></div><button class="btn gold" data-play-composition="${featured.movieId}">▶ WATCH FEATURE</button></div></div>${rest.length?`<div class="theater-row-head"><div><span>YOUR MOVIES</span><h2>More Adventures</h2></div></div><div class="streaming-grid">${rest.map(card).join('')}</div>`:''}`:'<div class="empty"><h2>Your theater is waiting.</h2><p>Create or import your first story, turn it into a movie, and premiere it here.</p><div class="actions"><button class="btn gold" data-action="new-movie">CREATE A STORY</button><button class="btn" data-action="import-story">UPLOAD A STORY</button></div></div>'}`)}
function editorPage(){const c=composition();if(!c)return recoveryPage('No movie timeline was found.','Return to a completed story and choose Build My Movie.');return TimelineEditor.render(c,state.editorSceneId,state.age)}
function playerPage(){const c=composition();if(!c)return recoveryPage('This movie could not be opened.','Its timeline may have been removed. You can rebuild it from My Movies.');return CinemaPlayer.render(c)}
function importPage(){return page('IMPORT YOUR STORY',`<div class="import-layout"><div><p class="script">Bring Your Own Adventure</p><h2>PASTE OR UPLOAD A STORY</h2><p>Paste a story, open a PDF, or select PNG/JPG/WebP pages. Every PDF or picture page becomes its own editable movie scene, in order. Everything stays on your device.</p><div class="import-formats"><span>PDF</span><span>PNG</span><span>JPG</span><span>WEBP</span><span>TXT</span><span>MARKDOWN</span><span>STORY PROJECT</span></div><div class="field"><label>STORY TEXT</label><textarea id="importStoryText" rows="14" placeholder="Once upon a time..."></textarea></div><label class="btn ghost upload-label" id="storyFileLabel"><span id="storyFileLabelText">📖 OPEN STORY PAGES</span><input id="storyFileInput" type="file" multiple accept=".pdf,.png,.jpg,.jpeg,.webp,.txt,.md,.json,application/pdf,image/png,image/jpeg,image/webp,text/plain,text/markdown,application/json" hidden></label><button class="btn gold" data-action="build-imported-story">BUILD TIMELINE 🎬</button><div class="pdf-progress" id="pdfProgress" hidden><i></i><span>Preparing your pages…</span></div></div><aside class="import-help"><span>📚</span><h3>PAGE-BY-PAGE MOVIES</h3><p>Choose up to 24 pictures together, or one PDF. Pages are compressed for reliable mobile playback and stored only in this browser.</p><ul><li>Choose image files in the order the story should play</li><li>Each PDF page stays paired with its own artwork and text</li><li>You can edit every scene afterward</li><li>No account or API is required</li></ul></aside></div>`)}
function recoveryPage(title,message){return page('MOVIE RECOVERY',`<div class="empty"><span style="font-size:60px">🛠️</span><h2>${esc(title)}</h2><p>${esc(message)}</p><button class="btn gold" data-action="movies">GO TO MY MOVIES</button></div>`)}
function page(title,body){return `<h1 class="page-title">${title}</h1><section class="card content-card">${body}</section>`}
function render(){if(state.route!=='player')CinemaPlayer.cleanup();document.documentElement.dataset.age=state.age;document.documentElement.dataset.route=state.route;document.documentElement.classList.toggle('reduced-motion',!!state.settings.reduced);let body=state.route==='home'?polishHome(home()):state.route==='create'?create():state.route==='director'?directorPage():state.route==='poster'?posterPage():state.route==='movies'?moviesPage():state.route==='characters'?charactersPage():state.route==='worlds'?worldsPage():state.route==='rewards'?rewardsPage():state.route==='settings'?settingsPage():state.route==='theater'?theaterPage():state.route==='editor'?editorPage():state.route==='player'?playerPage():state.route==='import'?importPage():polishHome(home());$('#app').innerHTML=state.route==='player'?body:shell(body);document.documentElement.style.fontSize=state.settings.textSize==='large'?'18px':state.settings.textSize==='small'?'14px':'16px';bind();$$('button').forEach(button=>{button.type='button';if(button.disabled)button.setAttribute('aria-disabled','true')});$$('.nav button').forEach(button=>{if(button.classList.contains('active'))button.setAttribute('aria-current','page')});$$('.switch').forEach(button=>{button.setAttribute('role','switch');button.setAttribute('aria-checked',String(button.classList.contains('on')));button.setAttribute('aria-label',button.closest('.setting')?.querySelector('span')?.textContent||'Setting')});if(state.route==='player'){const c=composition();if(c)CinemaPlayer.mount(c,{onMessage:toast,onFinish:()=>{c.status='Finished';saveComposition(c);toast('🌟 Your movie has finished!')}})}}
function route(r){state.route=r;persistState(false);render();scrollTo({top:0,behavior:state.settings.reduced?'auto':'smooth'})}
function toast(msg){const t=$('#toast');if(!t)return;t.textContent=msg;t.classList.add('show');clearTimeout(t._hideTimer);t._hideTimer=setTimeout(()=>t.classList.remove('show'),2300)}
function modal(title,body){const m=$('#modal');m.innerHTML=`<div class="modal-box"><button class="modal-close" data-action="close-modal">×</button><h2>${title}</h2>${body}</div>`;m.classList.add('open');m.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action))}
function randomCharacter(){const names=['Nova','Kai','Zuri','Milo','Ari','Luna','Skye','Jalen'],c=state.project.character;c.name=names[Math.floor(Math.random()*names.length)];c.skin=['#f5cfad','#dca578','#b97850','#9a5b3c','#6b3b29','#3e251e'][Math.floor(Math.random()*6)];c.hair=['Curly Puff','Braids','Waves','Short Curls','Locs','Straight','Covered'][Math.floor(Math.random()*7)];c.outfit=['Explorer Jacket','Science Suit','Hero Hoodie','Royal Adventure','Sports Gear','Music Star'][Math.floor(Math.random()*6)];c.personality=['Brave','Curious','Funny','Kind','Clever','Bold'][Math.floor(Math.random()*6)];c.role=['Explorer','Inventor','Guardian','Detective','Dreamer','Team Captain'][Math.floor(Math.random()*6)]}
function shakeMovieBox(){const box=$('.movie-box'),button=$('[data-action="surprise-project"]');if(button){button.disabled=true;button.textContent='✨ MAKING MOVIE…'}if(box){box.classList.remove('shaking');void box.offsetWidth;box.classList.add('shaking')}toast('🎲 Shaking up a complete surprise movie…');setTimeout(buildSurpriseMovie,650)}
function buildSurpriseMovie(){try{resetProject();randomCharacter();const p=state.project;p.world=structuredClone(WORLDS[Math.floor(Math.random()*WORLDS.length)]);for(const k of Object.keys(STORY_OPTIONS)){const a=STORY_OPTIONS[k];p.story[k]=a[Math.floor(Math.random()*a.length)]}p.packId=p.world.pack;p.currentScene=PACKS[p.packId].start;titleChoices();p.title=p.titleChoices[0];let steps=0;while(steps++<12){const scene=PACKS[p.packId].scenes[p.currentScene];if(!scene)throw new Error('The surprise story lost its next scene.');if(!scene.choices?.length){p.ending=scene.endingFlag||p.story.ending;p.badge=scene.badge||'Movie Maker';p.status='Completed';p.stage=5;break}const available=scene.choices.filter(c=>!c.requires||p.inventory.includes(c.requires));const choice=available[Math.floor(Math.random()*available.length)]||scene.choices.find(c=>!c.requires);if(!choice)throw new Error('The surprise story needs a different path.');p.choices.push({scene:scene.id,choice:choice.text,next:choice.nextScene});if(choice.itemReward&&!p.inventory.includes(choice.itemReward))p.inventory.push(choice.itemReward);if(choice.unlock&&!p.unlocks.includes(choice.unlock))p.unlocks.push(choice.unlock);if(choice.stat)p.stats[choice.stat]=(p.stats[choice.stat]||0)+1;p.starsEarned+=choice.starsReward||10;p.currentScene=choice.nextScene}if(p.status!=='Completed')throw new Error('The surprise story took too long to finish.');state.stars+=Math.max(50,p.starsEarned);if(!state.badges.includes(p.badge))state.badges.push(p.badge);saveProject(false);const movie=buildComposition(true);if(!movie)throw new Error('The movie timeline could not be prepared.');movie.status='Ready to Play';saveComposition(movie);route('player');toast('✨ Surprise! Your movie is ready to watch.')}catch(error){console.warn('Surprise movie recovery:',error);state.route='home';render();toast('The movie box needs one more shake. Your saved movies are safe!')}}
function startMovie(){const p=state.project,custom=$('#customTitle')?.value.trim(),missing=Object.keys(STORY_OPTIONS).filter(key=>!p.story[key]);if(missing.length)return toast(`Choose your ${missing[0]==='item'?'special item':missing[0]} before rolling camera.`);if(custom){p.title=custom;p.customTitle=true}if(!p.title)return toast('Choose a movie title or type your own before rolling camera.');p.packId=p.world.pack;p.currentScene=PACKS[p.packId].start;p.checkpoint=p.currentScene;p.stage=4;p.status='In Progress';saveProject(false);render()}
function chooseMovieChoice(index){const p=state.project,s=currentScene(),visible=(s.choices||[]).filter(c=>!c.requires||p.inventory.includes(c.requires)).slice(0,AGE[state.age].max),c=visible[index];if(!c)return;const leavingTwist=p.twistScene===s.id;p.checkpoint=p.currentScene;p.choices.push({scene:s.id,choice:c.text,next:c.nextScene});if(c.itemReward&&!p.inventory.includes(c.itemReward))p.inventory.push(c.itemReward);if(c.unlock&&!p.unlocks.includes(c.unlock))p.unlocks.push(c.unlock);if(c.stat)p.stats[c.stat]=(p.stats[c.stat]||0)+1;p.starsEarned+=c.starsReward||10;state.stars+=c.starsReward||10;p.currentScene=c.nextScene;if(p.pendingTwist&&!p.twistScene)p.twistScene=p.currentScene;else if(leavingTwist){p.pendingTwist='';p.twistScene=''}autosave();render();toast(`${c.itemReward?'◆ '+c.itemReward+' collected • ':''}⭐ +${c.starsReward||10}`)}
function reachFinale(){const p=state.project,s=currentScene(),strength=Object.entries(p.stats).sort((a,b)=>b[1]-a[1])[0];p.ending=s.endingFlag;p.badge=s.badge;p.hiddenStrength=strength[0];const bonus=strength[1]*5;p.status='Completed';p.stage=5;state.stars+=100+bonus;p.starsEarned+=100+bonus;['First Movie',p.badge].forEach(b=>{if(b&&!state.badges.includes(b))state.badges.push(b)});autosave();render()}
function applyMobileNavigation(){if(!matchMedia('(max-width:760px)').matches)return;const footer=$('.footer-ribbon'),mobile=$('.mobile-top');if(footer){footer.classList.add('mobile-bottom-nav');footer.innerHTML=`${[['home','⌂','HOME'],['create','🎬','CREATE'],['movies','🎞️','MOVIES'],['theater','🍿','THEATER']].map(([routeName,icon,label])=>`<button data-${routeName==='theater'?'action':'route'}="${routeName}" class="${state.route===routeName?'active':''}" aria-label="${label}"><span>${icon}</span><small>${label}</small></button>`).join('')}<button data-action="menu" aria-label="More navigation"><span>☰</span><small>MORE</small></button>`}if(mobile){const labels={home:'HOME',create:'CREATE',movies:'MY MOVIES',characters:'CHARACTERS',worlds:'WORLDS',rewards:'REWARDS',settings:'SETTINGS',theater:'THEATER',director:'DIRECTOR',poster:'POSTER',editor:'EDITOR',import:'IMPORT STORY'};const title=mobile.querySelector('strong');if(title)title.textContent=`STORY SPARK • ${labels[state.route]||'CINEMA'}`}}
function applyMobileDrawerChrome(){document.body.classList.remove('mobile-menu-open');if(!matchMedia('(max-width:760px)').matches)return;const sidebar=$('#sidebar'),app=$('.app');if(sidebar&&!sidebar.querySelector('.mobile-drawer-close'))sidebar.insertAdjacentHTML('afterbegin','<button class="mobile-drawer-close" data-action="close-mobile-menu" aria-label="Close navigation">×</button>');if(app&&!app.querySelector('.mobile-menu-scrim'))app.insertAdjacentHTML('beforeend','<button class="mobile-menu-scrim" data-action="close-mobile-menu" aria-label="Close navigation"></button>')}
function bindIntentionalTap(element,handler){if(!element)return;let start=null,moved=false,locked=false;element.onpointerdown=event=>{if(event.pointerType!=='touch'&&event.pointerType!=='pen')return;start={x:event.clientX,y:event.clientY};moved=false};element.onpointermove=event=>{if(start&&Math.hypot(event.clientX-start.x,event.clientY-start.y)>10)moved=true};element.onpointercancel=()=>{start=null;moved=true};element.onclick=event=>{const cancelled=moved;start=null;moved=false;if(cancelled||locked||element.disabled)return;locked=true;try{handler(event)}finally{setTimeout(()=>locked=false,320)}}}
function bindMobileTap(element,handler){if(!element)return;let active=false,suppressClick=false,releaseTimer=null;const arm=()=>{suppressClick=true;clearTimeout(releaseTimer);releaseTimer=setTimeout(()=>suppressClick=false,3000)},begin=event=>{if(event.pointerType==='mouse'||element.disabled)return;active=true;arm();event.preventDefault()},finish=event=>{if(event.pointerType==='mouse'||element.disabled||!active)return;active=false;arm();event.preventDefault();handler(event)},cancel=()=>active=false;if('PointerEvent'in window){element.onpointerdown=begin;element.onpointerup=finish;element.onpointercancel=cancel}else{element.ontouchstart=event=>{if(element.disabled)return;active=true;arm();event.preventDefault()};element.ontouchend=finish;element.ontouchcancel=cancel}element.onclick=event=>{if(suppressClick){suppressClick=false;clearTimeout(releaseTimer);return}if(!element.disabled)handler(event)}}
function bindMobileClick(element,handler){if(!element)return;element.onclick=event=>{if(!element.disabled)handler(event)}}
function setMobileDrawer(open){const sidebar=$('#sidebar'),scrim=$('.mobile-menu-scrim'),menu=$('.mobile-top [data-action="menu"]');sidebar?.classList.toggle('open',open);scrim?.classList.toggle('open',open);document.body.classList.toggle('mobile-menu-open',open);if(menu){menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close navigation':'Open navigation')}}
function applyMobileAppChrome(){if(!window.MobileApp||MobileApp.isStandalone())return;const nav=$('.nav'),mobile=$('.mobile-top');if(nav&&!nav.querySelector('[data-action="install-app"]'))nav.insertAdjacentHTML('afterend','<button class="install-app-card" data-action="install-app"><span>📲</span><div><strong>GET THE MOBILE APP</strong><small>Install on iPhone or Android</small></div></button>');if(mobile&&!mobile.querySelector('[data-action="install-app"]'))mobile.insertAdjacentHTML('beforeend','<button class="mobile-install" data-action="install-app" aria-label="Install Story Spark Cinema">📲</button>')}
async function installStorySparkApp(){if(!window.MobileApp)return toast('Mobile installation is not available in this browser.');const result=await MobileApp.install();if(result.status==='accepted'||result.status==='installed')return toast('🎬 Story Spark Cinema is ready on your home screen!');if(result.status==='dismissed')return toast('Installation cancelled. You can install anytime.');if(result.status==='ios-guide')return modal('INSTALL ON IPHONE OR IPAD','<div class="install-guide"><span>📲</span><ol><li>Open this page in <strong>Safari</strong>.</li><li>Tap the <strong>Share</strong> button at the bottom.</li><li>Choose <strong>Add to Home Screen</strong>.</li><li>Tap <strong>Add</strong>.</li></ol><p>Your stories and movies will stay available from the new app icon.</p></div>');return modal('INSTALL ON ANDROID','<div class="install-guide"><span>📲</span><ol><li>Open this page in <strong>Chrome</strong>.</li><li>Tap the three-dot menu.</li><li>Choose <strong>Install app</strong> or <strong>Add to Home screen</strong>.</li><li>Confirm <strong>Install</strong>.</li></ol><p>Story Spark Cinema will open like a full-screen app.</p></div>')}
function applyStarPhotoDom(){const put=(el,c,kind)=>{if(!el||!c?.photo)return;el.classList.add('has-star-photo',kind);const img=document.createElement('img');img.className='star-photo';img.src=c.photo;img.alt=`${c.name||'Movie star'} photo`;el.replaceChildren(img)};if(state.route==='poster')put($('.poster-avatar'),state.project.character,'poster-star-photo');if(state.route==='characters')$$('.character-library .saved-avatar').forEach((el,i)=>put(el,state.characters[i],'library-star-photo'))}
function prepareStarPhoto(file){return new Promise((resolve,reject)=>{if(!file||!/^image\/(jpeg|png|webp)$/i.test(file.type))return reject(new Error('Please choose a JPG, PNG, or WebP photo.'));if(file.size>10*1024*1024)return reject(new Error('Please choose a photo smaller than 10 MB.'));const reader=new FileReader();reader.onerror=()=>reject(new Error('That photo could not be read. Please try another one.'));reader.onload=()=>{const img=new Image();img.onerror=()=>reject(new Error('That photo could not be opened. Please try another one.'));img.onload=()=>{const scale=Math.min(1,900/Math.max(img.width,img.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);resolve(canvas.toDataURL('image/jpeg',.84))};img.src=reader.result};reader.readAsDataURL(file)})}
function prepareSceneImage(file,targetSize=180000){return new Promise((resolve,reject)=>{if(!file||!(/^image\/(jpeg|png|webp)$/i.test(file.type)||/\.(png|jpe?g|webp)$/i.test(file.name)))return reject(new Error('Story pages must be PNG, JPG, or WebP images.'));if(file.size>20*1024*1024)return reject(new Error(`${file.name} is over 20 MB. Choose a smaller image.`));const reader=new FileReader();reader.onerror=()=>reject(new Error(`${file.name} could not be read.`));reader.onload=()=>{const img=new Image();img.onerror=()=>reject(new Error(`${file.name} could not be opened.`));img.onload=()=>{let maxEdge=960,quality=.7,result='';for(let attempt=0;attempt<8;attempt+=1){const scale=Math.min(1,maxEdge/Math.max(img.width,img.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));const context=canvas.getContext('2d',{alpha:false});context.fillStyle='#fff';context.fillRect(0,0,canvas.width,canvas.height);context.drawImage(img,0,0,canvas.width,canvas.height);result=canvas.toDataURL('image/jpeg',quality);if(result.length<=targetSize)break;maxEdge=Math.max(420,Math.round(maxEdge*.82));quality=Math.max(.38,quality-.06)}if(result.length>targetSize*1.35)return reject(new Error(`${file.name} is too detailed to store safely on this phone.`));resolve(result)};img.src=reader.result};reader.readAsDataURL(file)})}
async function prepareImagePages(files,onProgress){const images=Array.from(files||[]);if(!images.length)throw new Error('Choose at least one PNG, JPG, or WebP page.');if(images.length>24)throw new Error('Choose 24 image pages or fewer at one time.');const target=Math.min(190000,Math.floor(2100000/images.length)),pages=[];let totalSize=0;for(let index=0;index<images.length;index+=1){onProgress?.(index+1,images.length);const image=await prepareSceneImage(images[index],target);totalSize+=image.length;if(totalSize>2200000)throw new Error('These pages need too much phone storage. Try fewer images at a time.');pages.push({pageNumber:index+1,name:images[index].name.replace(/\.[^.]+$/,''),text:'',image})}return pages}
function removeCompositionAssets(comp){for(const ref of comp?.uploadedAudio||[]){const stillUsed=state.compositions.some(item=>item.uploadedAudio?.some(other=>other.id===ref.id));if(!stillUsed)AudioStore.remove(ref.id).catch(error=>console.warn('Audio cleanup recovery:',error))}}
