 $$('[data-duplicate-movie]').forEach(b=>b.onclick=()=>{const original=state.movies.find(m=>m.id===b.dataset.duplicateMovie);if(!original)return;const copy=structuredClone(original),oldId=copy.id;copy.id='movie-'+Date.now();copy.title=(copy.title||'Untitled Movie')+' Copy';copy.created=new Date().toISOString();copy.updated=copy.created;state.movies.unshift(copy);const originalComp=state.compositions.find(c=>c.projectId===oldId);if(originalComp){const cc=structuredClone(originalComp);cc.movieId='composition-'+copy.id;cc.projectId=copy.id;cc.title=copy.title;cc.scenes.forEach((s,i)=>s.id=s.id+'-copy-'+Date.now()+'-'+i);cc.timeline=cc.scenes.map(s=>s.id);cc.createdDate=copy.created;cc.updatedDate=copy.updated;state.compositions.unshift(cc)}save();render();toast('Movie duplicated!')});
 $$('[data-duplicate-composition]').forEach(b=>b.onclick=()=>{const original=state.compositions.find(c=>c.movieId===b.dataset.duplicateComposition);if(!original)return;const copy=structuredClone(original),stamp=Date.now();copy.movieId='import-'+stamp;copy.projectId=null;copy.title=(copy.title||'Imported Story')+' Copy';copy.scenes.forEach((s,i)=>s.id=s.id+'-copy-'+stamp+'-'+i);copy.timeline=copy.scenes.map(s=>s.id);copy.createdDate=new Date().toISOString();copy.updatedDate=copy.createdDate;state.compositions.unshift(copy);save();render();toast('Imported movie duplicated!')});
