 $$('[data-player-action]').forEach(button=>bindMobileTap(button,()=>{const playerAction=button.dataset.playerAction;if(playerAction==='exit'){const current=composition();if(current)saveComposition(current);CinemaPlayer.cleanup();return route(current?.status==='Finished'?'theater':'editor')}CinemaPlayer.action(playerAction);if(['captions','narration'].includes(playerAction))save()}));if($('[data-player-volume]'))$('[data-player-volume]').oninput=e=>{CinemaPlayer.action('volume',e.target.value);save()};$$('[data-player-scene]').forEach(button=>bindMobileClick(button,()=>CinemaPlayer.jump(+button.dataset.playerScene)));
 if($('#storyFileInput'))$('#storyFileInput').onchange=async e=>{const input=e.target,files=Array.from(input.files||[]);if(!files.length)return;const label=$('#storyFileLabel'),labelText=$('#storyFileLabelText'),progress=$('#pdfProgress'),isImage=file=>/^image\/(png|jpeg|webp)$/i.test(file.type)||/\.(png|jpe?g|webp)$/i.test(file.name),showProgress=(current,total,message)=>{if(!progress)return;progress.hidden=false;progress.querySelector('i').style.width=`${Math.round(current/total*100)}%`;progress.querySelector('span').textContent=message};document.body.classList.add('file-import-active');try{if(label)label.classList.add('loading');if(labelText)labelText.textContent='✨ PREPARING YOUR PAGES…';if(files.every(isImage)){const pages=await prepareImagePages(files,(page,total)=>showProgress(page,total,`Preparing image ${page} of ${total}…`)),imported=MovieStudio.importPages(pages,state.age,{type:'images',title:files.length===1?files[0].name:'My Image Story'});saveComposition(imported);route('editor');toast(`🎬 ${pages.length} picture page${pages.length===1?'':'s'} became movie scenes.`)}else if(files.length===1&&(/\.pdf$/i.test(files[0].name)||files[0].type==='application/pdf')){const file=files[0];if(!window.PdfStoryReader)throw new Error('The PDF reader is still getting ready. Try once more.');const result=await PdfStoryReader.extract(file,(page,total)=>showProgress(page,total,`Reading page ${page} of ${total}…`)),imported=MovieStudio.importPages(result.pages,state.age,{type:'pdf',title:result.fileName});imported.sourceInformation={...imported.sourceInformation,pageCount:result.pageCount,hasExtractedText:result.hasExtractedText};saveComposition(imported);route('editor');toast(`🎬 PDF ready! ${result.pages.length} page${result.pages.length===1?'':'s'} became matching movie scenes.`)}else if(files.length===1){const file=files[0],text=await file.text();if(/\.json$/i.test(file.name)){const obj=JSON.parse(text),imported=MovieStudio.validate(obj.composition||obj);imported.movieId='import-'+Date.now();imported.updatedDate=new Date().toISOString();saveComposition(imported);route('editor')}else{$('#importStoryText').value=text;toast('Story file loaded—choose Build Timeline.')}}else throw new Error('Choose image pages together, or choose one PDF or text file at a time.')}catch(error){console.warn('Story import recovery:',error);toast(error.message||'That story file could not be read. Try pasting its text instead.')}finally{input.value='';document.body.classList.remove('file-import-active');window.dispatchEvent(new CustomEvent('storyspark-import-finished'));if(label)label.classList.remove('loading');if(labelText)labelText.textContent='📖 OPEN STORY PAGES';if(progress)progress.hidden=true}};
