 $$('[data-action="menu"]').forEach(menu=>{const topMenu=menu.closest('.mobile-top');if(topMenu)menu.innerHTML='<span class="hamburger-icon" aria-hidden="true"><i></i><i></i><i></i></span>';menu.setAttribute('aria-label',topMenu?'Open navigation':'More navigation');menu.setAttribute('aria-expanded','false');bindMobileTap(menu,()=>setMobileDrawer(!$('#sidebar')?.classList.contains('open')))});$$('[data-action="close-mobile-menu"]').forEach(button=>bindMobileTap(button,()=>setMobileDrawer(false)))
